fn resolve_current_crate() -> Result<String, String> {
    let cargo_toml = std::env::current_dir()
        .map_err(|e| format!("Failed to get current directory: {e}"))?
        .join("Cargo.toml");

    if !cargo_toml.exists() {
        return Err("No Cargo.toml found in current directory".to_string());
    }

    let content = fs::read_to_string(&cargo_toml)
        .map_err(|e| format!("Failed to read Cargo.toml: {e}"))?;

    // Simple parsing - look for name = "..." in [package] section
    let mut in_package = false;
    for line in content.lines() {
        let line = line.trim();
        if line == "[package]" {
            in_package = true;
            continue;
        }
        if line.starts_with('[') {
            in_package = false;
            continue;
        }
        if in_package && line.starts_with("name") {
            // Parse: name = "crate-name"
            if let Some(eq_pos) = line.find('=') {
                let value = line[eq_pos + 1..].trim();
                let value = value.trim_matches('"').trim_matches('\'');
                return Ok(value.to_string());
            }
        }
    }

    Err("No [package] section found in Cargo.toml (are you in the workspace root?)".to_string())
}

