fn run_all_builds(config: &Config, workspace_root: &Path) -> Vec<TestResult> {
    let mut results = Vec::new();

    // Build all (default target)
    print_section("cargo build (default target)");
    let result = run_cargo_build("cargo build", &[], workspace_root, config);
