    println!("                    Specifying rlibc-x2 also runs rlibc-x2-tests");
    println!();
    println!("Options:");
    println!("  -v, --verbose     Show full test output");
    println!("  -f, --fail-fast   Stop on first failure");
    println!("  -r, --release     Use release builds (default)");
