//! Project automation tasks
//!
//! # Usage
//!
//! ```text
//! cargo xtask test                  # run all tests (release builds, default)
//! cargo xtask test .                # test crate in current directory
//! cargo xtask test ex-x1            # test specific crate
//! cargo xtask test ex-x1 hw-x2      # test multiple crates
//! cargo xtask test ex-musl          # auto-detects musl target
//! cargo xtask test rlibc-x2         # includes rlibc-x2-tests binaries
//! cargo xtask test -v               # verbose output
//! cargo xtask test --debug          # use debug builds (faster iteration)
//! ```
//!
//! # Available Commands
//!
//! - `test` - Run repository tests (all, or specific crates)

use std::fs;
use std::path::Path;
use std::process::{Command, ExitCode, Stdio};

enum Subcommand {
    Build,
    Run,
    Test,
}

struct Config {
    subcommand: Subcommand,
    verbose: bool,
    fail_fast: bool,
    debug: bool,
    crates: Vec<String>, // Empty means all crates
}

struct TestResult {
    name: String,
    passed: bool,
    #[allow(dead_code)] // Captured for potential future use (e.g., detailed failure reports)
    output: String,
}

fn main() -> ExitCode {
    let config = parse_args();

    // Get workspace root (xtask is at workspace root level)
    let workspace_root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("Could not find workspace root");

    match config.subcommand {
        Subcommand::Build => run_builds(&config, workspace_root),
        Subcommand::Test => run_tests(&config, workspace_root),
    }
}

fn run_builds(config: &Config, workspace_root: &Path) -> ExitCode {
    let mut results = Vec::new();

    if config.crates.is_empty() {
        // Build all crates
        results.extend(run_all_builds(config, workspace_root));
    } else {
        // Build specified crates only
        results.extend(run_filtered_builds(config, workspace_root));
    }

    print_summary(&results)
}

fn run_all_builds(config: &Config, workspace_root: &Path) -> Vec<TestResult> {
    let mut results = Vec::new();

    // Build all (default target)
    print_section("cargo build (default target)");
    let result = run_cargo_build("cargo build", &[], workspace_root, config);
    let failed = !result.passed;
    results.push(result);
    if failed && config.fail_fast {
        return results;
    }

    // Build musl targets
    print_section("cargo build (musl target)");
    let result = run_cargo_build(
        "cargo build (musl)",
        &[
            "--target",
            "x86_64-unknown-linux-musl",
            "-p",
            "ex-musl",
            "-p",
            "hw-musl",
        ],
        workspace_root,
        config,
    );
    results.push(result);

    results
}

fn run_filtered_builds(config: &Config, workspace_root: &Path) -> Vec<TestResult> {
