//! Project automation tasks
//!
//! # Usage
//!
//! ```text
//! cargo xtask build                 # build all (debug default)
//! cargo xtask build .               # build crate in current directory
//! cargo xtask build ex-x1 --release # build specific crate (release)
//!
//! cargo xtask run hw-x1             # run specific crate (debug default)
//! cargo xtask run . --release       # run crate in current directory (release)
//!
//! cargo xtask test                  # run all tests (release default)
//! cargo xtask test . --debug        # test crate in current directory (debug)
//! cargo xtask test rlibc-x2         # includes rlibc-x2-tests binaries
//! ```
//!
//! # Available Commands
//!
//! - `build` - Build crates (debug default)
//! - `run` - Build and run crates (debug default)
//! - `test` - Run tests (release default, for size verification)

use std::fs;
use std::path::Path;
use std::process::{Command, ExitCode, Stdio};

enum Subcommand {
    Build,
    Run,
    Test,
}

struct Config {
    subcommand: Subcommand,
    verbose: bool,
    fail_fast: bool,
    debug: bool,
    crates: Vec<String>, // Empty means all crates
}

struct TestResult {
    name: String,
    passed: bool,
    #[allow(dead_code)] // Captured for potential future use (e.g., detailed failure reports)
    output: String,
}

fn main() -> ExitCode {
    let config = parse_args();

    // Get workspace root (xtask is at workspace root level)
    let workspace_root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("Could not find workspace root");

    match config.subcommand {
        Subcommand::Build => run_cargo_cmd("build", &config, workspace_root),
        Subcommand::Run => run_cargo_cmd("run", &config, workspace_root),
        Subcommand::Test => run_tests(&config, workspace_root),
    }
}

/// Generic handler for cargo build/run commands
fn run_cargo_cmd(cmd_name: &str, config: &Config, workspace_root: &Path) -> ExitCode {
    let mut results = Vec::new();

    if config.crates.is_empty() {
        // Run on all crates
        results.extend(run_cargo_cmd_all(cmd_name, config, workspace_root));
    } else {
        // Run on specified crates only
        results.extend(run_cargo_cmd_filtered(cmd_name, config, workspace_root));
    }

    print_summary(&results)
}

fn run_cargo_cmd_all(cmd_name: &str, config: &Config, workspace_root: &Path) -> Vec<TestResult> {
    let mut results = Vec::new();

    // Default target
    print_section(&format!("cargo {cmd_name} (default target)"));
    let result = exec_cargo_cmd(cmd_name, &format!("cargo {cmd_name}"), &[], workspace_root, config);
    let failed = !result.passed;
    results.push(result);
    if failed && config.fail_fast {
        return results;
    }

    // Musl targets
    print_section(&format!("cargo {cmd_name} (musl target)"));
    let result = exec_cargo_cmd(
        cmd_name,
        &format!("cargo {cmd_name} (musl)"),
        &[
            "--target",
            "x86_64-unknown-linux-musl",
            "-p",
            "ex-musl",
            "-p",
            "hw-musl",
        ],
        workspace_root,
        config,
    );
    results.push(result);

    results
}

fn run_cargo_cmd_filtered(cmd_name: &str, config: &Config, workspace_root: &Path) -> Vec<TestResult> {
    let mut results = Vec::new();

    // Separate crates by target (musl vs default)
    let (musl_crates, default_crates): (Vec<_>, Vec<_>) = config
        .crates
        .iter()
        .partition(|c| c.contains("musl"));

    // Default target crates
    for crate_name in &default_crates {
        print_section(&format!("cargo {cmd_name} ({crate_name})"));

        let args = vec!["-p", crate_name.as_str()];
        let result = exec_cargo_cmd(cmd_name, &format!("cargo {cmd_name} ({crate_name})"), &args, workspace_root, config);
        let failed = !result.passed;
        results.push(result);
        if failed && config.fail_fast {
            return results;
        }
    }

    // Musl target crates
    for crate_name in &musl_crates {
        print_section(&format!("cargo {cmd_name} musl ({crate_name})"));

        let args = vec!["--target", "x86_64-unknown-linux-musl", "-p", crate_name.as_str()];
        let result = exec_cargo_cmd(cmd_name, &format!("cargo {cmd_name} musl ({crate_name})"), &args, workspace_root, config);
        let failed = !result.passed;
        results.push(result);
        if failed && config.fail_fast {
            return results;
        }
    }

    results
}

fn exec_cargo_cmd(
    cmd_name: &str,
    display_name: &str,
    extra_args: &[&str],
    workspace_root: &Path,
    config: &Config,
) -> TestResult {
    let mut cmd = Command::new("cargo");
    cmd.arg(cmd_name);
    if !config.debug {
        cmd.arg("--release");
    }
    cmd.args(extra_args);
    cmd.current_dir(workspace_root);

    if config.verbose {
        let status = cmd.status();
        let passed = matches!(status, Ok(s) if s.success());
        println!();
        TestResult {
            name: display_name.to_string(),
            passed,
            output: String::new(),
        }
    } else {
        cmd.stdout(Stdio::piped());
        cmd.stderr(Stdio::piped());

        match cmd.output() {
            Ok(output) => {
                let passed = output.status.success();
                let stderr = String::from_utf8_lossy(&output.stderr);

                if passed {
                    println!("  ok\n");
                } else {
                    println!("  FAILED\n");
                    eprintln!("{stderr}");
                }

                TestResult {
                    name: display_name.to_string(),
                    passed,
                    output: stderr.to_string(),
                }
            }
            Err(e) => {
                eprintln!("  Failed to run cargo {cmd_name}: {e}");
                TestResult {
                    name: display_name.to_string(),
                    passed: false,
                    output: e.to_string(),
                }
            }
        }
    }
}

fn run_tests(config: &Config, workspace_root: &Path) -> ExitCode {
    let mut results = Vec::new();

    if config.crates.is_empty() {
        // Run all tests (original behavior)
        results.extend(run_all_tests(config, workspace_root));
    } else {
        // Run tests for specified crates only
        results.extend(run_filtered_tests(config, workspace_root));
    }

    print_summary(&results)
}

fn run_all_tests(config: &Config, workspace_root: &Path) -> Vec<TestResult> {
    let mut results = Vec::new();

    // 1. cargo test (default target)
    print_section("cargo test (default target)");
    let result = run_cargo_test("cargo test", &[], workspace_root, config);
    let failed = !result.passed;
    results.push(result);
    if failed && config.fail_fast {
        return results;
    }

    // 2. cargo test (musl target)
    print_section("cargo test (musl target)");
    let result = run_cargo_test(
        "cargo test (musl)",
        &[
            "--target",
            "x86_64-unknown-linux-musl",
            "-p",
            "ex-musl",
            "-p",
            "hw-musl",
        ],
        workspace_root,
        config,
    );
    let failed = !result.passed;
    results.push(result);
    if failed && config.fail_fast {
        return results;
    }

    // 3. rlibc-x2-tests
    print_section("rlibc-x2-tests");
    let rlibc_x2_results = run_rlibc_x2_tests(workspace_root, config);
    for result in rlibc_x2_results {
        let failed = !result.passed;
        results.push(result);
        if failed && config.fail_fast {
            return results;
        }
    }

    results
}

fn run_filtered_tests(config: &Config, workspace_root: &Path) -> Vec<TestResult> {
    let mut results = Vec::new();

    // Separate crates by target (musl vs default)
    let (musl_crates, default_crates): (Vec<_>, Vec<_>) = config
        .crates
        .iter()
        .partition(|c| c.contains("musl"));

    // Check if rlibc-x2 is requested (triggers rlibc-x2-tests)
    let run_rlibc_x2_tests_flag = config.crates.iter().any(|c| c == "rlibc-x2");

    // Run default target crates (each individually for clear per-crate results)
    for crate_name in &default_crates {
        print_section(&format!("cargo test ({crate_name})"));

        let args = vec!["-p", crate_name.as_str()];
        let result = run_cargo_test(&format!("cargo test ({crate_name})"), &args, workspace_root, config);
        let failed = !result.passed;
        results.push(result);
        if failed && config.fail_fast {
            return results;
        }
    }

    // Run musl target crates (each individually for clear per-crate results)
    for crate_name in &musl_crates {
        print_section(&format!("cargo test musl ({crate_name})"));

        let args = vec!["--target", "x86_64-unknown-linux-musl", "-p", crate_name.as_str()];
        let result = run_cargo_test(&format!("cargo test musl ({crate_name})"), &args, workspace_root, config);
        let failed = !result.passed;
        results.push(result);
        if failed && config.fail_fast {
            return results;
        }
    }

    // Run rlibc-x2-tests if rlibc-x2 was specified
    if run_rlibc_x2_tests_flag {
        print_section("rlibc-x2-tests");
        let rlibc_x2_results = run_rlibc_x2_tests(workspace_root, config);
        for result in rlibc_x2_results {
            let failed = !result.passed;
            results.push(result);
            if failed && config.fail_fast {
                return results;
            }
        }
    }

    results
}

fn parse_args() -> Config {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut args_iter = args.iter();

    // Parse subcommand (first argument)
    let subcommand = match args_iter.next().map(|s| s.as_str()) {
        Some("build") => Subcommand::Build,
        Some("run") => Subcommand::Run,
        Some("test") => Subcommand::Test,
        Some("-h" | "--help") => {
            print_main_help();
            std::process::exit(0);
        }
        Some(other) => {
            eprintln!("Unknown command: {other}");
            eprintln!("Use --help for usage information");
            std::process::exit(1);
        }
        None => {
            print_main_help();
            std::process::exit(0);
        }
    };

    // Default: build/run use debug (faster iteration), test uses release (verify sizes)
    let debug_default = matches!(subcommand, Subcommand::Build | Subcommand::Run);

    let mut config = Config {
        subcommand,
        verbose: false,
        fail_fast: false,
        debug: debug_default,
        crates: Vec::new(),
    };

    // Parse options and positional arguments for the subcommand
    for arg in args_iter {
        match arg.as_str() {
            "-v" | "--verbose" => config.verbose = true,
            "-f" | "--fail-fast" | "--fail" => config.fail_fast = true,
            "-r" | "--release" => config.debug = false,
            "-d" | "--debug" => config.debug = true,
            "-h" | "--help" => {
                match config.subcommand {
                    Subcommand::Build => print_cmd_help("build"),
                    Subcommand::Run => print_cmd_help("run"),
                    Subcommand::Test => print_test_help(),
                }
                std::process::exit(0);
            }
            other if other.starts_with('-') => {
                eprintln!("Unknown option: {other}");
                eprintln!("Use --help for usage information");
                std::process::exit(1);
            }
            "." => {
                match resolve_current_crate() {
                    Ok(Some(name)) => config.crates.push(name),
                    Ok(None) => {} // Workspace root - leave crates empty for "all"
                    Err(e) => {
                        eprintln!("{e}");
                        std::process::exit(1);
                    }
                }
            }
            crate_name => {
                config.crates.push(crate_name.to_string());
            }
        }
    }

    config
}

/// Resolve "." to the crate name in the current directory
/// Returns None if at workspace root (meaning "all"), Some(name) for a crate, or error
fn resolve_current_crate() -> Result<Option<String>, String> {
    let cargo_toml = std::env::current_dir()
        .map_err(|e| format!("Failed to get current directory: {e}"))?
        .join("Cargo.toml");

    if !cargo_toml.exists() {
        return Err("No Cargo.toml found in current directory".to_string());
    }

    let content = fs::read_to_string(&cargo_toml)
        .map_err(|e| format!("Failed to read Cargo.toml: {e}"))?;

    // Simple parsing - look for name = "..." in [package] section
    let mut in_package = false;
    for line in content.lines() {
        let line = line.trim();
        if line == "[package]" {
            in_package = true;
            continue;
        }
        if line.starts_with('[') {
            in_package = false;
            continue;
        }
        if in_package && line.starts_with("name") {
            // Parse: name = "crate-name"
            if let Some(eq_pos) = line.find('=') {
                let value = line[eq_pos + 1..].trim();
                let value = value.trim_matches('"').trim_matches('\'');
                return Ok(Some(value.to_string()));
            }
        }
    }

    // No [package] section - likely workspace root, treat as "all"
    Ok(None)
}

