     1→//! Project automation tasks
     2→//!
     3→//! All commands default to debug builds for faster iteration. Use `-r` for release.
     4→//!
     5→//! # Usage
     6→//!
     7→//! ```text
     8→//! cargo xtask build                 # build all (debug)
     9→//! cargo xtask build ex-x1 -r        # build specific crate (release)
    10→//!
    11→//! cargo xtask run hw-x1             # run specific crate
    12→//! cargo xtask run .                 # run crate in current directory
    13→//!
    14→//! cargo xtask test                  # run all tests
    15→//! cargo xtask test . -r             # test with release builds
    16→//! cargo xtask test rlibc-x2         # includes rlibc-x2-tests binaries
    17→//! ```
    18→//!
    19→//! # Available Commands
    20→//!
    21→//! - `build` - Build crates
    22→//! - `run` - Build and run crates
    23→//! - `test` - Run tests
    24→
    25→use std::fs;
    26→use std::path::Path;
    27→use std::process::{Command, ExitCode, Stdio};
    28→
    29→enum Subcommand {
    30→    Build,
    31→    Run,
    32→    Test,
    33→}
    34→
    35→struct Config {
    36→    subcommand: Subcommand,
    37→    verbose: bool,
    38→    fail_fast: bool,
    39→    debug: bool,
    40→    crates: Vec<String>, // Empty means all crates
    41→}
    42→
    43→struct TestResult {
    44→    name: String,
    45→    passed: bool,
    46→    #[allow(dead_code)] // Captured for potential future use (e.g., detailed failure reports)
    47→    output: String,
    48→}
    49→
    50→fn main() -> ExitCode {
    51→    let config = parse_args();
    52→
    53→    // Get workspace root (xtask is at workspace root level)
    54→    let workspace_root = Path::new(env!("CARGO_MANIFEST_DIR"))
    55→        .parent()
    56→        .expect("Could not find workspace root");
    57→
    58→    match config.subcommand {
    59→        Subcommand::Build => run_cargo_cmd("build", &config, workspace_root),
    60→        Subcommand::Run => run_cargo_cmd("run", &config, workspace_root),
    61→        Subcommand::Test => run_tests(&config, workspace_root),
    62→    }
    63→}
    64→
    65→/// Generic handler for cargo build/run commands
    66→fn run_cargo_cmd(cmd_name: &str, config: &Config, workspace_root: &Path) -> ExitCode {
    67→    let mut results = Vec::new();
    68→
    69→    if config.crates.is_empty() {
    70→        // Run on all crates
    71→        results.extend(run_cargo_cmd_all(cmd_name, config, workspace_root));
    72→    } else {
    73→        // Run on specified crates only
    74→        results.extend(run_cargo_cmd_filtered(cmd_name, config, workspace_root));
    75→    }
    76→
    77→    print_summary(&results)
    78→}
    79→
    80→fn run_cargo_cmd_all(cmd_name: &str, config: &Config, workspace_root: &Path) -> Vec<TestResult> {
    81→    let mut results = Vec::new();
    82→
    83→    // Default target
    84→    print_section(&format!("cargo {cmd_name} (default target)"));
    85→    let result = exec_cargo_cmd(cmd_name, &format!("cargo {cmd_name}"), &[], workspace_root, config);
    86→    let failed = !result.passed;
    87→    results.push(result);
    88→    if failed && config.fail_fast {
    89→        return results;
    90→    }
    91→
    92→    // Musl targets
    93→    print_section(&format!("cargo {cmd_name} (musl target)"));
    94→    let result = exec_cargo_cmd(
    95→        cmd_name,
    96→        &format!("cargo {cmd_name} (musl)"),
    97→        &[
    98→            "--target",
    99→            "x86_64-unknown-linux-musl",
   100→            "-p",
   101→            "ex-musl",
   102→            "-p",
   103→            "hw-musl",
   104→        ],
   105→        workspace_root,
   106→        config,
   107→    );
   108→    results.push(result);
   109→
   110→    results
   111→}
   112→
   113→fn run_cargo_cmd_filtered(cmd_name: &str, config: &Config, workspace_root: &Path) -> Vec<TestResult> {
   114→    let mut results = Vec::new();
   115→
   116→    // Separate crates by target (musl vs default)
   117→    let (musl_crates, default_crates): (Vec<_>, Vec<_>) = config
   118→        .crates
   119→        .iter()
   120→        .partition(|c| c.contains("musl"));
   121→
   122→    // Default target crates
   123→    for crate_name in &default_crates {
   124→        print_section(&format!("cargo {cmd_name} ({crate_name})"));
   125→
   126→        let args = vec!["-p", crate_name.as_str()];
   127→        let result = exec_cargo_cmd(cmd_name, &format!("cargo {cmd_name} ({crate_name})"), &args, workspace_root, config);
   128→        let failed = !result.passed;
   129→        results.push(result);
   130→        if failed && config.fail_fast {
   131→            return results;
   132→        }
   133→    }
   134→
   135→    // Musl target crates
   136→    for crate_name in &musl_crates {
   137→        print_section(&format!("cargo {cmd_name} musl ({crate_name})"));
   138→
   139→        let args = vec!["--target", "x86_64-unknown-linux-musl", "-p", crate_name.as_str()];
   140→        let result = exec_cargo_cmd(cmd_name, &format!("cargo {cmd_name} musl ({crate_name})"), &args, workspace_root, config);
   141→        let failed = !result.passed;
   142→        results.push(result);
   143→        if failed && config.fail_fast {
   144→            return results;
   145→        }
   146→    }
   147→
   148→    results
   149→}
   150→
   151→fn exec_cargo_cmd(
   152→    cmd_name: &str,
   153→    display_name: &str,
   154→    extra_args: &[&str],
   155→    workspace_root: &Path,
   156→    config: &Config,
   157→) -> TestResult {
   158→    let mut cmd = Command::new("cargo");
   159→    cmd.arg(cmd_name);
   160→    if !config.debug {
   161→        cmd.arg("--release");
   162→    }
   163→    cmd.args(extra_args);
   164→    cmd.current_dir(workspace_root);
   165→
   166→    if config.verbose {
   167→        let status = cmd.status();
   168→        let passed = matches!(status, Ok(s) if s.success());
   169→        println!();
   170→        TestResult {
   171→            name: display_name.to_string(),
   172→            passed,
   173→            output: String::new(),
   174→        }
   175→    } else {
   176→        cmd.stdout(Stdio::piped());
   177→        cmd.stderr(Stdio::piped());
   178→
   179→        match cmd.output() {
   180→            Ok(output) => {
   181→                let passed = output.status.success();
   182→                let stderr = String::from_utf8_lossy(&output.stderr);
   183→
   184→                if passed {
   185→                    println!("  ok\n");
   186→                } else {
   187→                    println!("  FAILED\n");
   188→                    eprintln!("{stderr}");
   189→                }
   190→
   191→                TestResult {
   192→                    name: display_name.to_string(),
   193→                    passed,
   194→                    output: stderr.to_string(),
   195→                }
   196→            }
   197→            Err(e) => {
   198→                eprintln!("  Failed to run cargo {cmd_name}: {e}");
   199→                TestResult {
   200→                    name: display_name.to_string(),
   201→                    passed: false,
   202→                    output: e.to_string(),
   203→                }
   204→            }
   205→        }
   206→    }
   207→}
   208→
   209→fn run_tests(config: &Config, workspace_root: &Path) -> ExitCode {
   210→    let mut results = Vec::new();
   211→
   212→    if config.crates.is_empty() {
   213→        // Run all tests (original behavior)
   214→        results.extend(run_all_tests(config, workspace_root));
   215→    } else {
   216→        // Run tests for specified crates only
   217→        results.extend(run_filtered_tests(config, workspace_root));
   218→    }
   219→
   220→    print_summary(&results)
   221→}
   222→
   223→fn run_all_tests(config: &Config, workspace_root: &Path) -> Vec<TestResult> {
   224→    let mut results = Vec::new();
   225→
   226→    // 1. cargo test (default target)
   227→    print_section("cargo test (default target)");
   228→    let result = run_cargo_test("cargo test", &[], workspace_root, config);
   229→    let failed = !result.passed;
   230→    results.push(result);
   231→    if failed && config.fail_fast {
   232→        return results;
   233→    }
   234→
   235→    // 2. cargo test (musl target)
   236→    print_section("cargo test (musl target)");
   237→    let result = run_cargo_test(
   238→        "cargo test (musl)",
   239→        &[
   240→            "--target",
   241→            "x86_64-unknown-linux-musl",
   242→            "-p",
   243→            "ex-musl",
   244→            "-p",
   245→            "hw-musl",
   246→        ],
   247→        workspace_root,
   248→        config,
   249→    );
   250→    let failed = !result.passed;
   251→    results.push(result);
   252→    if failed && config.fail_fast {
   253→        return results;
   254→    }
   255→
   256→    // 3. rlibc-x2-tests
   257→    print_section("rlibc-x2-tests");
   258→    let rlibc_x2_results = run_rlibc_x2_tests(workspace_root, config);
   259→    for result in rlibc_x2_results {
   260→        let failed = !result.passed;
   261→        results.push(result);
   262→        if failed && config.fail_fast {
   263→            return results;
   264→        }
   265→    }
   266→
   267→    results
   268→}
   269→
   270→fn run_filtered_tests(config: &Config, workspace_root: &Path) -> Vec<TestResult> {
   271→    let mut results = Vec::new();
   272→
   273→    // Separate crates by target (musl vs default)
   274→    let (musl_crates, default_crates): (Vec<_>, Vec<_>) = config
   275→        .crates
   276→        .iter()
   277→        .partition(|c| c.contains("musl"));
   278→
   279→    // Check if rlibc-x2 is requested (triggers rlibc-x2-tests)
   280→    let run_rlibc_x2_tests_flag = config.crates.iter().any(|c| c == "rlibc-x2");
   281→
   282→    // Run default target crates (each individually for clear per-crate results)
   283→    for crate_name in &default_crates {
   284→        print_section(&format!("cargo test ({crate_name})"));
   285→
   286→        let args = vec!["-p", crate_name.as_str()];
   287→        let result = run_cargo_test(&format!("cargo test ({crate_name})"), &args, workspace_root, config);
   288→        let failed = !result.passed;
   289→        results.push(result);
   290→        if failed && config.fail_fast {
   291→            return results;
   292→        }
   293→    }
   294→
   295→    // Run musl target crates (each individually for clear per-crate results)
   296→    for crate_name in &musl_crates {
   297→        print_section(&format!("cargo test musl ({crate_name})"));
   298→
   299→        let args = vec!["--target", "x86_64-unknown-linux-musl", "-p", crate_name.as_str()];
   300→        let result = run_cargo_test(&format!("cargo test musl ({crate_name})"), &args, workspace_root, config);
   301→        let failed = !result.passed;
   302→        results.push(result);
   303→        if failed && config.fail_fast {
   304→            return results;
   305→        }
   306→    }
   307→
   308→    // Run rlibc-x2-tests if rlibc-x2 was specified
   309→    if run_rlibc_x2_tests_flag {
   310→        print_section("rlibc-x2-tests");
   311→        let rlibc_x2_results = run_rlibc_x2_tests(workspace_root, config);
   312→        for result in rlibc_x2_results {
   313→            let failed = !result.passed;
   314→            results.push(result);
   315→            if failed && config.fail_fast {
   316→                return results;
   317→            }
   318→        }
