   324→fn parse_args() -> Config {
   325→    let args: Vec<String> = std::env::args().skip(1).collect();
   326→    let mut args_iter = args.iter();
   327→
   328→    // Parse subcommand (first argument)
   329→    let subcommand = match args_iter.next().map(|s| s.as_str()) {
   330→        Some("build") => Subcommand::Build,
   331→        Some("run") => Subcommand::Run,
   332→        Some("test") => Subcommand::Test,
   333→        Some("-h" | "--help") => {
   334→            print_main_help();
   335→            std::process::exit(0);
   336→        }
   337→        Some(other) => {
   338→            eprintln!("Unknown command: {other}");
   339→            eprintln!("Use --help for usage information");
   340→            std::process::exit(1);
   341→        }
   342→        None => {
   343→            print_main_help();
   344→            std::process::exit(0);
   345→        }
   346→    };
   347→
   348→    let mut config = Config {
   349→        subcommand,
   350→        verbose: false,
   351→        fail_fast: false,
   352→        debug: true, // Default to debug for faster iteration; use -r for release
   353→        crates: Vec::new(),
   354→    };
   355→
   356→    // Parse options and positional arguments for the subcommand
   357→    for arg in args_iter {
   358→        match arg.as_str() {
   359→            "-v" | "--verbose" => config.verbose = true,
   360→            "-f" | "--fail-fast" | "--fail" => config.fail_fast = true,
   361→            "-r" | "--release" => config.debug = false,
   362→            "-d" | "--debug" => config.debug = true,
   363→            "-h" | "--help" => {
   364→                match config.subcommand {
   365→                    Subcommand::Build => print_cmd_help("build"),
   366→                    Subcommand::Run => print_cmd_help("run"),
   367→                    Subcommand::Test => print_test_help(),
   368→                }
   369→                std::process::exit(0);
   370→            }
   371→            other if other.starts_with('-') => {
   372→                eprintln!("Unknown option: {other}");
   373→                eprintln!("Use --help for usage information");
   374→                std::process::exit(1);
   375→            }
   376→            "." => {
   377→                match resolve_current_crate() {
   378→                    Ok(Some(name)) => config.crates.push(name),
   379→                    Ok(None) => {} // Workspace root - leave crates empty for "all"
   380→                    Err(e) => {
   381→                        eprintln!("{e}");
   382→                        std::process::exit(1);
   383→                    }
   384→                }
   385→            }
   386→            crate_name => {
   387→                config.crates.push(crate_name.to_string());
   388→            }
   389→        }
   390→    }
   391→
   392→    config
   393→}
