   395→/// Resolve "." to the crate name in the current directory
   396→/// Returns None if at workspace root (meaning "all"), Some(name) for a crate, or error
   397→fn resolve_current_crate() -> Result<Option<String>, String> {
   398→    let cargo_toml = std::env::current_dir()
   399→        .map_err(|e| format!("Failed to get current directory: {e}"))?
   400→        .join("Cargo.toml");
   401→
   402→    if !cargo_toml.exists() {
   403→        return Err("No Cargo.toml found in current directory".to_string());
   404→    }
   405→
   406→    let content = fs::read_to_string(&cargo_toml)
   407→        .map_err(|e| format!("Failed to read Cargo.toml: {e}"))?;
   408→
   409→    // Simple parsing - look for name = "..." in [package] section
   410→    let mut in_package = false;
   411→    for line in content.lines() {
   412→        let line = line.trim();
   413→        if line == "[package]" {
   414→            in_package = true;
   415→            continue;
   416→        }
   417→        if line.starts_with('[') {
   418→            in_package = false;
   419→            continue;
   420→        }
   421→        if in_package && line.starts_with("name") {
   422→            // Parse: name = "crate-name"
   423→            if let Some(eq_pos) = line.find('=') {
   424→                let value = line[eq_pos + 1..].trim();
   425→                let value = value.trim_matches('"').trim_matches('\'');
   426→                return Ok(Some(value.to_string()));
   427→            }
   428→        }
   429→    }
   430→
   431→    // No [package] section - likely workspace root, treat as "all"
   432→    Ok(None)
   433→}
