   525→        }
   526→    } else {
   527→        cmd.stdout(Stdio::piped());
   528→        cmd.stderr(Stdio::piped());
   529→
   530→        match cmd.output() {
   531→            Ok(output) => {
   532→                let stdout = String::from_utf8_lossy(&output.stdout);
   533→                let stderr = String::from_utf8_lossy(&output.stderr);
   534→                let combined = format!("{stderr}\n{stdout}");
   535→                let passed = output.status.success();
   536→
   537→                // Collect crate names from stderr ("Running" lines)
   538→                let crate_names: Vec<String> = stderr
   539→                    .lines()
   540→                    .filter(|line| line.trim_start().starts_with("Running "))
   541→                    .filter_map(|line| {
   542→                        line.find("deps/").and_then(|pos| {
   543→                            let rest = &line[pos + 5..];
   544→                            rest.find('-').map(|dash| rest[..dash].replace('_', "-"))
   545→                        })
   546→                    })
   547→                    .collect();
   548→
   549→                // Parse test results from stdout
   550→                let mut total_passed = 0;
   551→                let mut total_failed = 0;
   552→                let mut total_ignored = 0;
   553→                let mut crate_idx = 0;
   554→
   555→                for line in stdout.lines() {
   556→                    if line.contains("test result:") {
   557→                        let (p, f, i) = parse_test_result(line);
   558→                        let crate_name = crate_names
   559→                            .get(crate_idx)
   560→                            .map(|s| s.as_str())
   561→                            .unwrap_or("unknown");
   562→                        crate_idx += 1;
   563→
   564→                        if p > 0 || f > 0 || i > 0 {
   565→                            let status = if f > 0 {
   566→                                "FAIL"
   567→                            } else if p > 0 {
   568→                                "ok"
   569→                            } else {
   570→                                "skip"
   571→                            };
   572→                            println!(
   573→                                "  {crate_name}: {status} ({p} passed, {f} failed, {i} ignored)"
   574→                            );
   575→                        }
   576→                        total_passed += p;
   577→                        total_failed += f;
   578→                        total_ignored += i;
   579→                    }
   580→                }
   581→
   582→                if passed {
   583→                    println!(
   584→                        "  Total: {total_passed} passed, {total_failed} failed, {total_ignored} ignored\n"
   585→                    );
   586→                } else {
   587→                    println!(
   588→                        "  FAILED: {total_passed} passed, {total_failed} failed, {total_ignored} ignored\n"
   589→                    );
   590→                    println!("{combined}");
   591→                }
   592→
   593→                TestResult {
   594→                    name: name.to_string(),
   595→                    passed,
   596→                    output: combined.to_string(),
   597→                }
   598→            }
   599→            Err(e) => {
   600→                eprintln!("  Failed to run cargo test: {e}");
   601→                TestResult {
   602→                    name: name.to_string(),
   603→                    passed: false,
   604→                    output: e.to_string(),
   605→                }
   606→            }
   607→        }
   608→    }
   609→}
   610→
   611→fn parse_test_result(line: &str) -> (u32, u32, u32) {
   612→    // Parse "test result: ok. X passed; Y failed; Z ignored; ..."
   613→    let mut passed = 0;
   614→    let mut failed = 0;
   615→    let mut ignored = 0;
   616→
   617→    // Extract numbers before "passed", "failed", "ignored"
   618→    for part in line.split(';') {
   619→        let part = part.trim();
   620→        if part.ends_with(" passed") {
   621→            // Find the number - it's the last word before "passed"
   622→            let words: Vec<&str> = part.split_whitespace().collect();
   623→            if words.len() >= 2
   624→                && let Ok(n) = words[words.len() - 2].parse()
   625→            {
   626→                passed = n;
   627→            }
   628→        } else if part.ends_with(" failed") {
   629→            let words: Vec<&str> = part.split_whitespace().collect();
   630→            if words.len() >= 2
   631→                && let Ok(n) = words[words.len() - 2].parse()
   632→            {
   633→                failed = n;
   634→            }
   635→        } else if part.ends_with(" ignored") {
   636→            let words: Vec<&str> = part.split_whitespace().collect();
   637→            if words.len() >= 2
   638→                && let Ok(n) = words[words.len() - 2].parse()
   639→            {
   640→                ignored = n;
   641→            }
   642→        }
   643→    }
   644→
   645→    (passed, failed, ignored)
   646→}
   647→
   648→fn run_rlibc_x2_tests(workspace_root: &Path, config: &Config) -> Vec<TestResult> {
   649→    let mut results = Vec::new();
   650→
   651→    // First, build the test binaries
   652→    print!("  Building rlibc-x2-tests... ");
   653→
   654→    let mut build_cmd = Command::new("cargo");
   655→    build_cmd.args(["build", "-p", "rlibc-x2-tests"]);
   656→    if !config.debug {
   657→        build_cmd.arg("--release");
   658→    }
   659→    let build_output = build_cmd
   660→        .current_dir(workspace_root)
   661→        .stdout(Stdio::piped())
   662→        .stderr(Stdio::piped())
   663→        .output();
   664→
   665→    match build_output {
   666→        Ok(output) if output.status.success() => {
   667→            println!("ok");
   668→        }
   669→        Ok(output) => {
   670→            println!("FAILED");
   671→            let stderr = String::from_utf8_lossy(&output.stderr);
   672→            eprintln!("{stderr}");
   673→            results.push(TestResult {
   674→                name: "rlibc-x2-tests (build)".to_string(),
   675→                passed: false,
   676→                output: stderr.to_string(),
   677→            });
   678→            return results;
   679→        }
   680→        Err(e) => {
   681→            println!("FAILED");
   682→            eprintln!("  Failed to run cargo build: {e}");
   683→            results.push(TestResult {
   684→                name: "rlibc-x2-tests (build)".to_string(),
   685→                passed: false,
   686→                output: e.to_string(),
   687→            });
   688→            return results;
   689→        }
   690→    }
   691→
   692→    // Find and run test binaries
   693→    let profile = if config.debug { "debug" } else { "release" };
   694→    let target_dir = workspace_root.join(format!("target/{profile}"));
   695→
   696→    let test_binaries: Vec<_> = fs::read_dir(&target_dir)
   697→        .into_iter()
   698→        .flatten()
   699→        .filter_map(|e| e.ok())
   700→        .filter(|e| {
   701→            let name = e.file_name();
   702→            let name = name.to_string_lossy();
   703→            name.ends_with("-tests") && e.path().is_file()
