   730→            Ok(output) => {
   731→                let passed = output.status.success();
   732→                let stdout = String::from_utf8_lossy(&output.stdout);
   733→                let stderr = String::from_utf8_lossy(&output.stderr);
   734→                let combined = format!("{stdout}{stderr}");
   735→
   736→                if passed {
